interface Label
class Box<C> { fun <T:Label> fallback(value:T?=null):T?=value }
fun bad():String?=Box<String>().fallback<String>()

interface Label
class Box<C> { fun <T:Label> first(vararg items:T):T=items[0] }
fun bad():String=Box<Int>().first("bad")

interface Label
interface Api<C> { fun <T:Label> count(vararg items:T):Int }
class Impl<C>:Api<C> { override fun <R> count(vararg items:R):Int=items.size }

interface Label
interface Api<C> { fun <T:Label> first(vararg items:T):T }
fun bad(api:Api<String>):String=api.first("bad")
